class Solution {
public:
    long long continuousSubarrays(vector<int>& nums) {
        unordered_map<int,int> freq;
        long long ans = 0;
        int left = 0;
        int n = nums.size();
        for (int right = 0; right < n; right++) {
            freq[nums[right]]++;
            while (true) {
                int mn = INT_MAX, mx = INT_MIN;
                for (auto& kv : freq) {
                    mn = min(mn, kv.first);
                    mx = max(mx, kv.first);
                }
                if (mx - mn <= 2) break;
                freq[nums[left]]--;
                if (freq[nums[left]] == 0) freq.erase(nums[left]);
                left++;
            }
            ans += right - left + 1;
        }
        return ans;
    }
};
